using namespace std;
​
// 自定义比较函数
bool compare(const string &x, const string &y) {
    return x + y < y + x;
}
​
// 去除前导零
string formatPrint(const string &result) {
    size_t non_zero_pos = result.find_first_not_of('0');
    return (non_zero_pos == string::npos) ? "0" : result.substr(non_zero_pos);
}
​
string min_combination(vector<string> &zeroArr, vector<string> &noZeroArr) {
    // 排序
    sort(zeroArr.begin(), zeroArr.end(), compare);
    sort(noZeroArr.begin(), noZeroArr.end(), compare);
​
    // 拼接全零部分
    string zero_result = accumulate(zeroArr.begin(), zeroArr.end(), string());
​
    if (noZeroArr.empty()) {
        return formatPrint(zero_result);
    }
​
    // 选择最优的头部（第一个字符最小的）,不关要考虑字典序还需要考虑长度
    int best_index = 0;
    for (int i = 1; i < noZeroArr.size(); i++) {
        if (noZeroArr[i][0] != noZeroArr[0][0]) break;
        if (noZeroArr[i] + zero_result + noZeroArr[0] < noZeroArr[0] + zero_result + noZeroArr[i]) {
            best_index = i;
        }
    }
​
    // 结果拼接
    ostringstream result;
    result << noZeroArr[best_index] << zero_result;

    for (int i = 0; i < noZeroArr.size(); i++) {
        if (i != best_index) result << noZeroArr[i];
    }
​
    return result.str();
}
​
int main() {
    // 有前导零和无前导零的
    vector<string> zeroArr, noZeroArr;
    string s;
    while (cin >> s) {
        (s[0] == '0' ? zeroArr : noZeroArr).push_back(s);
    }
    cout << min_combination(zeroArr, noZeroArr) << endl;
    return 0;
}
