const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
/**
 * 去除字符串前导零
 */
function formatPrint(result) {
    return result.replace(/^0+/, "") || "0";
}
​
/**
 * 计算最小拼接数
 */
function minCombination(zeroArr, noZeroArr) {
    // 按照拼接规则排序
    zeroArr.sort((a, b) => (a + b).localeCompare(b + a));
    noZeroArr.sort((a, b) => (a + b).localeCompare(b + a));
​
    // 拼接所有零前缀的部分
    const zeroResult = zeroArr.join("");
​
    // 如果没有非零数，返回处理后的零字符串
    if (noZeroArr.length === 0) {
        return formatPrint(zeroResult);
    }
​
    // 选择最优的非零头部
    let bestIndex = 0;
    for (let i = 1; i < noZeroArr.length; i++) {
        if (noZeroArr[i][0] !== noZeroArr[0][0]) break;
        if ((noZeroArr[i] + zeroResult + noZeroArr[0]) < (noZeroArr[0] + zeroResult + noZeroArr[i])) {
            bestIndex = i;
        }
    }
​
    // 组合最终结果
    return noZeroArr[bestIndex] + zeroResult + noZeroArr.slice(0, bestIndex).join("") + noZeroArr.slice(bestIndex + 1).join("");
}
​
let input = [];
rl.on("line", (line) => {
    input = line.split(" ");
}).on("close", () => {
    const zeroArr = input.filter(s => s.startsWith("0"));
    const noZeroArr = input.filter(s => !s.startsWith("0"));
    console.log(minCombination(zeroArr, noZeroArr));
});
