package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strings"
)
​
/**
 * 自定义比较函数
 */
func compare(x, y string) bool {
    return x+y < y+x
}
​
/**
 * 去除字符串前导零
 */
func formatPrint(result string) string {
    result = strings.TrimLeft(result, "0")
    if result == "" {
        return "0"
    }
    return result
}
​
/**
 * 计算最小拼接数
 */
func minCombination(zeroArr, noZeroArr []string) string {
    sort.Slice(zeroArr, func(i, j int) bool { return compare(zeroArr[i], zeroArr[j]) })
    sort.Slice(noZeroArr, func(i, j int) bool { return compare(noZeroArr[i], noZeroArr[j]) })
​
    zeroResult := strings.Join(zeroArr, "")
​
    if len(noZeroArr) == 0 {
        return formatPrint(zeroResult)
    }
​
    bestIndex := 0
    for i := 1; i < len(noZeroArr); i++ {
        if noZeroArr[i][0] != noZeroArr[0][0] {
            break
        }
        if noZeroArr[i]+zeroResult+noZeroArr[0] < noZeroArr[0]+zeroResult+noZeroArr[i] {
            bestIndex = i
        }
    }
​
    var result strings.Builder
    result.WriteString(noZeroArr[bestIndex])
    result.WriteString(zeroResult)
    for i := range noZeroArr {
        if i != bestIndex {
            result.WriteString(noZeroArr[i])
        }
    }
​
    return result.String()
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    input := strings.Fields(scanner.Text())
​
    var zeroArr, noZeroArr []string
    for _, s := range input {
        if s[0] == '0' {
            zeroArr = append(zeroArr, s)
        } else {
            noZeroArr = append(noZeroArr, s)
        }
    }
​
    fmt.Println(minCombination(zeroArr, noZeroArr))
}
